<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {useServiceContext} from '@/composables/useServiceContext'
import {asApiError,requestBytes} from '@/api/client'
import {availableSupportActions,directTargetLink,isTicket,isSupportEvent,isPage,query,supportActions,supportStatus,type Ticket,type SupportEvent,type SupportTarget} from '@/api/modules/clientServices'
import {getBusiness,businessLink,domains,type Target} from '@/api/modules/operations'
import {validSupplyId,type SupplyAsset} from '@/api/modules/supply'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
import PrivateAssetPicker from '@/components/PrivateAssetPicker.vue'
const session=useSessionStore(),route=useRoute(),router=useRouter(),operator=computed(()=>route.meta.supportOperator===true),creating=computed(()=>route.meta.supportView==='new'),id=computed(()=>String(route.params.ticketId||''))
const kind=ref('FEEDBACK'),title=ref(''),text=ref(''),targetDomain=ref(''),targetId=ref(''),assets=ref<SupplyAsset[]>([]),uploadLocked=ref(false),action=ref(''),status=ref('')
const dirty=computed(()=>!!(title.value||text.value||assets.value.length)),ui=useServiceContext(()=>operator.value?null:session.selectedId||null,()=>dirty.value,()=>uploadLocked.value),{error,notice,busy,pending}=ui
const tickets=ref<Ticket[]>([]),ticket=ref<Ticket|null>(null),events=ref<SupportEvent[]>([]),cursor=ref<string|number|null>(null),historyCursor=ref<string|number|null>(null),loading=ref(false)
const locked=computed(()=>busy.value||!!pending.value||uploadLocked.value),base=computed(()=>operator.value?'/support/operations/tickets':'/support/tickets'),routeBase=computed(()=>operator.value?'/support/operations':'/support/tickets'),actions=computed(()=>ticket.value?availableSupportActions(ticket.value.current_status,operator.value):[])
const domainNames:Record<string,string>={ARTIST_PUBLIC:'公开艺人',STOCK_PUBLIC:'公开影片',NOTICE_PUBLIC:'公开通告',CUSTOMIZATION:'我的故事',TRADE:'原交易订单',PRODUCTION:'制作项目',PROJECTS:'项目发行',FINANCE:'结算',SUPPLY:'我的作品',LICENSE:'许可',GIGS:'商单',NOTICES:'通告办理',PRIVACY:'隐私请求',STOCK:'我的影片商品',AUDITIONS:'试镜预约',ENGAGEMENT:'活动与经营',COCREATION:'共创房间',REDEMPTION:'已获权益'}
let initialized=false
function initialize(){initialized=true;void load()}
let serial=0
function reset(){serial++;tickets.value=[];ticket.value=null;events.value=[];cursor.value=historyCursor.value=null;loading.value=false;title.value=text.value=action.value='';assets.value=[];uploadLocked.value=false;kind.value='FEEDBACK';targetDomain.value=typeof route.query.domain==='string'&&Object.hasOwn(domainNames,route.query.domain)?route.query.domain:'';targetId.value=validSupplyId(route.query.record)?String(route.query.record):''}
async function load(more=false){error.value=null;if(!ui.ready.value||loading.value||!operator.value&&!session.selectedId)return;const n=++serial;loading.value=true;if(creating.value){loading.value=false;return}if(id.value){ticket.value=null;events.value=[];historyCursor.value=null;const target=id.value,r=await ui.read(base.value+'/'+target,(v):v is Ticket=>isTicket(v)&&v.id===target&&(operator.value||v.party_id===session.selectedId));if(n!==serial)return;ticket.value=r;if(r){if(!actions.value.includes(action.value))action.value='';await loadHistory()}loading.value=false;return}const old=more?cursor.value:null;if(!more){tickets.value=[];cursor.value=null}const r=await ui.read(base.value+query({status:status.value,cursor:old,limit:20}),isPage((v):v is Ticket=>isTicket(v)&&(operator.value||v.party_id===session.selectedId)));if(n!==serial)return;if(r){if(old!==null&&r.next_cursor===old)ui.fail('反馈分页没有更新，请刷新。');else{tickets.value=more?[...tickets.value,...r.items]:r.items;cursor.value=r.next_cursor}}loading.value=false}
async function loadHistory(more=false){if(!ticket.value||more&&!historyCursor.value)return;const target=ticket.value.id,old=more?historyCursor.value:null,r=await ui.read(base.value+'/'+target+'/history'+query({cursor:old,limit:20}),isPage(isSupportEvent,'number'));if(!r){if(error.value&&[403,404,409].includes(error.value.status)){ticket.value=null;events.value=[];historyCursor.value=null}return}if(ticket.value?.id!==target)return;if(old!==null&&r.next_cursor===old){ui.fail('处理记录分页没有更新，请刷新反馈详情。');return}events.value=more?[...events.value,...r.items]:r.items;historyCursor.value=r.next_cursor}
async function submit(){if(locked.value||!title.value.trim()||!text.value.trim()||targetDomain.value&&!validSupplyId(targetId.value))return;const target=targetDomain.value?{domain:targetDomain.value,record_id:targetId.value}:null;await ui.write('/support/tickets',{kind:kind.value,title:title.value.trim(),text:text.value.trim(),target,asset_ids:assets.value.map(a=>a.id)},(v):v is Ticket=>isTicket(v)&&v.party_id===session.selectedId&&v.kind===kind.value,async r=>{title.value=text.value='';assets.value=[];await router.push('/support/tickets/'+r.id)})}
async function act(){const t=ticket.value;if(!t||locked.value||!actions.value.includes(action.value)||!text.value.trim())return;await ui.write(base.value+'/'+t.id+'/actions',{action:action.value,text:text.value.trim(),asset_ids:!operator.value&&action.value==='SUPPLEMENT'?assets.value.map(a=>a.id):[]},(v):v is Ticket=>isTicket(v)&&v.id===t.id,async()=>{text.value=action.value='';assets.value=[];await load()},{ifMatch:t.object_version});if(error.value?.status===412)await load()}
async function download(asset:string){if(!ticket.value)return;const signature=ui.signature.value;try{const blob=await requestBytes(base.value+'/'+ticket.value.id+'/assets/'+asset+'/content',{token:session.token,actingParty:operator.value?null:session.selectedId});if(signature!==ui.signature.value)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='反馈材料-'+asset;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(signature===ui.signature.value){error.value=asApiError(e);if([403,404,409].includes(error.value.status)){ticket.value=null;events.value=[];historyCursor.value=null}}}}
async function original(t:SupportTarget){const direct=directTargetLink(t);if(direct){await router.push(direct);return}if(Object.hasOwn(domains,t.domain)){const signature=ui.signature.value;try{const r=await getBusiness(ui.identity(),t as Target);if(signature===ui.signature.value)await router.push(businessLink(t as Target,r))}catch(e){if(signature===ui.signature.value)error.value=asApiError(e)}}else notice.value='请回相应原业务列表核对本条记录；反馈不会授予额外原业务权限。'}
watch(ui.revision,()=>{reset();if(initialized&&ui.ready.value)void load()},{flush:'sync'})
watch(status,()=>{ui.cancelReads();serial++;loading.value=false;tickets.value=[];cursor.value=null;void load()})
reset()
</script>
<template><ServiceWorkspace :title="creating?'提交反馈或举报':operator?'客服处理':'我的反馈与举报'" intro="记录问题、查看答复并补充材料。举报需核查；退款、争议和隐私请求仍按原业务办理。" :account-only="operator" :locked="locked" :dirty="dirty" :error="error" :notice="notice" @ready="initialize"><div class="service-tabs"><RouterLink to="/support/tickets">我的反馈</RouterLink><RouterLink to="/support/new">提交问题</RouterLink><RouterLink to="/support/operations">客服处理</RouterLink><RouterLink to="/operations/notifications">消息通知</RouterLink></div><p v-if="operator" class="service-muted">需独立客服处理授权；不得处理本人或关联身份的工单，页面入口不授予权限。</p><section v-if="pending" class="service-pending"><p>结果尚未确认，文字、附件和原请求均已保留。</p><button class="outline" :disabled="busy" @click="ui.retry">恢复原请求</button></section><form v-if="creating" class="supply-card" @submit.prevent="submit"><fieldset :disabled="busy||!!pending"><div class="service-form"><label>问题类型<select v-model="kind"><option value="FEEDBACK">使用反馈</option><option value="REPORT">举报线索</option></select></label><label>标题<input v-model="title" maxlength="200" required></label><label class="wide">问题说明<textarea v-model="text" maxlength="4000" rows="6" required/></label><label>关联原业务（可选）<select v-model="targetDomain"><option value="">普通反馈，不关联业务</option><option v-for="(label,key) in domainNames" :key="key" :value="key">{{label}}</option></select></label><label v-if="targetDomain">本人获准的原记录编号<input v-model.trim="targetId" maxlength="36" required></label></div><p class="service-muted">从原业务的“反馈或举报”进入会带入编号；没有获准编号时请选择普通反馈。</p><h2>私有问题材料（可选）</h2><PrivateAssetPicker v-model="assets" :disabled="busy||!!pending" @lock="uploadLocked=$event"/><button class="primary" :disabled="locked||!title.trim()||!text.trim()||!!targetDomain&&!validSupplyId(targetId)">确认提交问题</button></fieldset></form><section v-else-if="!ticket" class="supply-card"><div class="service-form"><label>处理状态<select v-model="status" :disabled="locked"><option value="">全部</option><option v-for="(label,key) in supportStatus" :key="key" :value="key">{{label}}</option></select></label><button class="outline" :disabled="locked||loading" @click="load()">刷新反馈记录</button></div><p v-if="loading" role="status">正在读取…</p><article v-for="t in tickets" :key="t.id" class="service-result"><p class="service-muted">{{t.kind==='REPORT'?'举报线索':'使用反馈'}} · {{new Date(t.updated_at).toLocaleString()}}</p><h2>{{t.title}}</h2><p>{{supportStatus[t.current_status]}}</p><RouterLink :to="routeBase+'/'+t.id" class="button-link outline">查看处理记录</RouterLink></article><p v-if="!tickets.length&&!cursor&&!loading&&!error">暂无当前身份可查看的问题记录。</p><button v-if="cursor" class="outline" :disabled="locked||loading" @click="load(true)">继续读取反馈</button></section><template v-if="ticket"><section class="supply-card"><h2>{{ticket.title}}</h2><p class="service-status">{{supportStatus[ticket.current_status]}}</p><p class="service-id">工单 {{ticket.id}} · 版本 {{ticket.object_version}}</p><button v-if="ticket.target&&!operator" class="outline" :disabled="locked" @click="original(ticket.target)">返回关联原业务</button><p v-if="ticket.target" class="service-muted">关联{{domainNames[ticket.target.domain]||ticket.target.domain}}：{{ticket.target.record_id}}</p><button class="outline" :disabled="locked||loading" @click="load()">刷新处理状态</button><ol class="service-history"><li v-for="event in events" :key="event.object_version"><p><strong>{{event.actor_kind==='APPLICANT'?'本人':'客服'}} · {{supportActions[event.action]}}</strong> <span class="service-muted">{{new Date(event.created_at).toLocaleString()}}</span></p><p class="service-text">{{event.text}}</p><div class="service-actions"><button v-for="asset in event.asset_ids" :key="asset" class="outline" :disabled="locked" @click="download(asset)">读取本次材料 {{asset.slice(0,8)}}</button></div></li></ol><button v-if="historyCursor" class="outline" :disabled="locked" @click="loadHistory(true)">继续读取后续处理记录</button><p class="service-muted">已正式提交的附件保留在各次处理记录中，新补件不会替换原材料。</p></section><form v-if="actions.length" class="supply-card" @submit.prevent="act"><fieldset :disabled="busy||!!pending"><h2>本次处理</h2><label class="service-field">选择操作<select v-model="action" :disabled="locked" required><option value="">请选择</option><option v-for="a in actions" :key="a" :value="a">{{supportActions[a]}}</option></select></label><label class="service-field">本次说明<textarea v-model="text" rows="5" maxlength="4000" required/></label><PrivateAssetPicker v-if="!operator&&action==='SUPPLEMENT'" v-model="assets" :disabled="busy||!!pending" @lock="uploadLocked=$event"/><button class="primary" :disabled="locked||!action||!text.trim()">确认本次处理</button></fieldset></form></template></ServiceWorkspace></template>
